const shapes={person:'<circle cx="24" cy="13" r="7"/><path d="M10 42v-8a14 14 0 0 1 28 0v8M17 42v-8m14 8v-8"/>',bank:'<path d="m5 17 19-11 19 11ZM8 42h32M8 21h32M12 22v15m12-15v15m12-15v15M6 38h36"/>',firm:'<path d="M6 42V22l12 6V17l12 7V7h9l3 35ZM12 34h3m7 0h3m7 0h3"/>',shop:'<path d="M7 22v20h34V22M4 22l5-15h30l5 15M4 22q5 8 10 0 5 8 10 0 5 8 10 0 5 8 10 0M14 42V30h10v12m7-12h5v6h-5Z"/>',coin:'<circle cx="24" cy="24" r="18"/><path d="m16 15 8 11 8-11M24 26v11m-8-11h16m-16 6h16"/>'};
const svg=k=>`<svg viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[k]}</svg>`;
const actor=(k,n,s='')=>`<div class="actor">${svg(k)}<b>${n}</b><small>${s}</small></div>`;
const transfer=s=>`<div class="transfer">${s}</div>`;
const receipt=(rows)=>`<div class="receipt">${rows.map(([a,b])=>`<div class="row"><span>${a}</span><b>${b}</b></div>`).join('')}</div>`;
const titles=['央行货币从哪里来','贷款创造存款','存款变成工资','工资用来消费','偿还本金，存款减少','利率影响下一笔贷款','通胀改变购买力'];
const step=(i,title,desc,diagram,take,more='')=>`<section class="chapter" id="step${i}"><span class="number">${i}</span><h2>${title}</h2><p class="description">${desc}</p><div class="diagram">${diagram}</div><p class="take">${take}</p>${more?`<details class="expand"><summary>展开理解</summary><p>${more}</p></details>`:''}</section>`;
document.body.innerHTML=`<header class="top"><div class="brand">${svg('coin')}宏观基础</div><a href="index.html">投资版</a></header><main class="shell"><div class="heading"><span class="eyebrow">MONEY → CREDIT → ECONOMY</span><h1>钱从哪里来，又去了哪里？</h1><p>先看钱的产生，再跟着一家面包店，走完借款、发工资、消费与还款的过程。</p></div><div class="page"><nav class="toc" aria-label="知识顺序"><strong>沿着这条线阅读</strong>${titles.map((t,i)=>`<a href="#step${i+1}"><span>${i+1}</span>${t}</a>`).join('')}<div class="divider"></div><a href="money.html">货币深入图解</a><a href="rates.html">利率深入图解</a><a href="inflation.html">通胀深入图解</a></nav><article class="story"><div class="origin"><b>先分清：现金和账户里的数字，来源不同。</b><p>纸币由央行发行；日常使用的银行存款，很多是在商业银行发放贷款时产生的。下面先讲两者的区别，再追踪新增的一笔存款。</p></div>
${step(1,'央行发行现金，也创造银行的准备金','央行可以通过购买资产等操作，增加商业银行在央行的准备金账户余额；商业银行再用准备金兑换现金，满足取现需求。',`<div class="lane">${actor('bank','中央银行','发行基础货币')}${transfer('准备金记入银行账户')}${actor('bank','商业银行','持有央行准备金')}${transfer('兑换现金 · 居民取现')}${actor('person','居民','获得纸币')}</div><p class="caption">这里展示来源关系，不是“央行直接把钱免费发给居民”。</p>`,'央行货币包括现金与银行准备金；居民的银行存款是商业银行的负债。','准备金用于银行间结算，公众通常不能直接持有。取现通常只是把已有存款换成现金，不等于个人财富增加。央行创造准备金也可能通过向银行提供贷款等方式进行。')}
${step(2,'面包店借款，账户里出现一笔新存款','面包店获批 10,000 元贷款。银行同时记两笔账：对面包店的贷款资产增加，面包店的存款余额增加。',`<div class="lane">${actor('bank','商业银行')}${transfer('批准贷款')}${actor('firm','面包店')}</div><div class="controls"><span>点击看记账变化</span><button id="before" aria-pressed="true">贷款前</button><button id="after" aria-pressed="false">贷款后</button></div><div class="balance" style="margin-top:12px">${receipt([['银行新增贷款资产','<span id="asset">¥0</span>'],['银行新增存款负债','<span id="liability">¥0</span>']])}<span class="balance-symbol">＝</span>${receipt([['面包店可用存款','<span id="cash">¥0</span>'],['面包店贷款债务','<span id="debt">¥0</span>']])}</div>`,'存款增加的同时，债务也增加。创造了支付手段，并没有凭空创造净财富。','银行放贷受到资本、流动性、监管、信用风险和借款需求等约束。不是先把某位储户的账户扣掉，再把同一笔存款交给借款人。')}
${step(3,'面包店支付工资，存款转给居民','面包店用新增存款支付 2,000 元工资。为了看清这笔钱，暂不计算其他收入和支出。',`<div class="lane">${actor('firm','面包店','存款 ¥10,000 → ¥8,000')}${transfer('工资 ¥2,000')}${actor('person','员工','存款 ¥0 → ¥2,000')}</div><p class="caption">本例新增存款合计仍为 10,000 元，只是换了持有人。</p>`,'支付工资是存款转移。劳动和生产创造商品与服务，账户余额本身不是实际产出。')}
${step(4,'居民购买面包，部分存款回到企业','员工花 100 元购买面包。企业获得销售收入，居民得到实际商品。',`<div class="lane">${actor('person','居民','存款 ¥2,000 → ¥1,900')}${transfer('支付 ¥100')}${actor('shop','面包店','存款 ¥8,000 → ¥8,100')}</div><div class="mechanism"><span>面包店提供商品</span>→<span>居民消费</span>→<span>销售收入支持后续经营</span></div>`,'你的支出成为别人的收入。同一笔存款可以在经济中反复流动。')}
${step(5,'企业偿还贷款本金，对应存款减少','面包店从账户中偿还 1,000 元本金。银行的贷款资产与存款负债同时减少。',`<div class="lane">${actor('firm','面包店','存款 ¥8,100 → ¥7,100')}${transfer('偿还本金 ¥1,000')}${actor('bank','商业银行','贷款余额 ¥10,000 → ¥9,000')}</div><p class="caption">企业与居民合计新增存款：10,000 → 9,000 元。这里不含利息。</p>`,'借款可以创造存款，偿还本金会减少存款。这条过程不是只能增加、不能减少。')}
${step(6,'利率，改变下一笔借款的成本','现在看一个新的决定：面包店要不要再借 10,000 元？一年期单利贷款，利率越高，需要支付的利息越多。',`<div class="two"><div class="mini"><small>假设年利率 3%</small><b>一年利息 ¥300</b><div class="sub">借款 10,000 × 3%</div></div><div class="mini warm"><small>假设年利率 6%</small><b>一年利息 ¥600</b><div class="sub">借款 10,000 × 6%</div></div></div><div class="mechanism"><span>融资更贵</span>→<span>部分扩张计划推迟</span>→<span>新增需求可能放缓</span></div>`,'利率影响新借款和消费的选择，再逐步影响经济活动；不是立刻改写所有贷款合同。','这是其他条件相近时的方向，幅度和时点并不确定。政策利率经市场和银行传导到贷款利率，固定利率合同通常不随市场利率即时调整。')}
${step(7,'需求与供给的变化，最终影响物价','如果购买需求增加得比面包供应更快，价格可能上涨。下面是价格上涨如何影响同样 100 元预算的示例。',`<div class="two"><div class="mini"><small>每件 ¥10</small><b>100 元买 10 件</b><div class="dots" aria-hidden="true">${'<i></i>'.repeat(10)}</div></div><div class="mini warm"><small>每件 ¥12</small><b>100 元买约 8.3 件</b><div class="dots" aria-hidden="true">${'<i></i>'.repeat(8)}<i class="faded"></i><i class="faded"></i></div></div></div><p class="caption">方块只示意完整商品数量，精确购买力为 100 ÷ 12 ≈ 8.33 件。</p><div class="mechanism"><span>需求或成本变化</span>→<span>总体物价变化</span>→<span>货币购买力变化</span></div>`,'单件面包涨价不等于通胀。通胀指一篮子商品与服务的总体价格持续上涨。','生产能力、原材料成本、预期和供给冲击都影响物价，新增存款不意味着价格立即等比例上涨。通胀放缓是上涨速度变慢，不等于价格下降。')}
<div class="bottom"><span>你已走完：货币产生 → 流通 → 回收 → 利率 → 购买力</span><a href="#step1">回到起点 ↑</a></div><p class="footer">全部金额为简化教学示例。第 2–5 步跟踪同一笔新增存款，第 6–7 步为后续独立情景。<br>参考：<a href="https://www.bankofengland.co.uk/explainers/how-is-money-created" target="_blank" rel="noopener">英格兰银行：货币如何创造</a> · <a href="https://www.ecb.europa.eu/ecb-and-you/explainers/tell-me-more/html/what_is_inflation.en.html" target="_blank" rel="noopener">欧洲央行：什么是通胀</a></p></article></div></main>`;
function loan(after){for(const id of ['asset','liability','cash','debt'])document.querySelector('#'+id).textContent=after?'¥10,000':'¥0';document.querySelector('#after').setAttribute('aria-pressed',String(after));document.querySelector('#before').setAttribute('aria-pressed',String(!after))}document.querySelector('#before').onclick=()=>loan(false);document.querySelector('#after').onclick=()=>loan(true);
const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){document.querySelectorAll('.toc a').forEach(a=>a.classList.toggle('current',a.hash==='#'+e.target.id))}},{rootMargin:'-10% 0px -65% 0px'});document.querySelectorAll('.chapter').forEach(s=>observer.observe(s));
